{"command": "echo 'import tornado.httpserver
import tornado.ioloop
import tornado.web

class MainHandler(tornado.web.RequestHandler):
    def get(self):
        self.write("You requested %s\n" % self.request.uri)

if __name__ == '__main__':
    app = tornado.web.Application([
        (r"/echo", MainHandler),
    ])
    http_server = tornado.httpserver.HTTPServer(app)
    http_server.listen(8888)
    tornado.ioloop.IOLoop.instance().start()' > /testbed/test_server.py && python3 /testbed/test_server.py &"}

